/**
 * Returns the app's Application title (navigation profile) by reading the web manifest the runtime generates. Falls back to the document title.
 * @returns {Promise.<string>}
 */
export async function JSA_GetAppName() {
	// BEGIN USER CODE
	// The navigation profile's Application title, from the web manifest the runtime generates; when that cannot be
	// read, the part of the tab title before " - ".
	const fromTitle = () => {
		// The tab title is "<application title> - <page title>"; with an empty application title it reads
		// "- <page title>", and the page title is not the app name.
		const match = (document.title || "").match(/^(.+?)\s+-\s+/);
		return match ? match[1].trim() : "";
	};
	const fromManifest = async () => {
		try {
			const link = document.querySelector("link[rel='manifest']");
			const href = link ? link.getAttribute("href") : "manifest.webmanifest";
			const response = await fetch(href, { credentials: "same-origin" });
			if (!response.ok) {
				return "";
			}
			const manifest = await response.json();
			return ((manifest && (manifest.name || manifest.short_name)) || "").trim();
		} catch (error) {
			return "";
		}
	};
	return (await fromManifest()) || fromTitle();
	// END USER CODE
}
